#!/usr/bin/env python3
from pathlib import Path
import hashlib,re

SRC=Path('market-navigator-turn18-pre-ship.html')
OUT=Path('market-navigator-turn25-pre-ship.html')
EXPECTED='4a52c7e764513024176aea80cc13c56e05370c11'
raw=SRC.read_bytes()
blob=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()
assert blob==EXPECTED,(blob,EXPECTED)
s=raw.decode()

def one(old,new,label):
    global s
    n=s.count(old)
    assert n==1,f'{label}: expected one anchor, found {n}'
    s=s.replace(old,new,1)

def between(a,b,new,label):
    global s
    i=s.find(a); assert i>=0,f'{label}: start not found'
    j=s.find(b,i); assert j>=0,f'{label}: end not found'
    s=s[:i]+new+s[j:]

# Identity is the only change before governed reconstruction.
one('Market Navigator · Turn 18','Market Navigator · Turn 25','title')
s=s.replace('TURN 18 PRE-SHIP','TURN 25 CONSOLIDATION')
s=s.replace('Turn 18</strong>','Turn 25</strong>')

# Permanent frame: Explore is physically absent. Add lives inside NOW.
one('<button class="nav" data-view="explore">EXPLORE</button>','','explore nav')
i=s.index('<section class="view" id="view-explore">')
j=s.index('<section class="view" id="view-library">',i)
s=s[:i]+s[j:]

# Retire the Component modal physically, not by hiding it.
i=s.index('<div class="modal hidden" id="analysisModal">')
j=s.index('</main></section></div><script>',i)
s=s[:i]+s[j:]

# NOW Add picker is the sole discovery surface.
picker='''<div class="picker hidden" id="nowPicker"><div class="pickerHead"><input id="nowPickerSearch" class="search" placeholder="Search Add"><button class="btn" id="nowPickerClose">×</button></div><div class="cats" id="nowPickerCats" style="padding:6px 8px"></div><div id="nowPickerList"></div></div><div class="card aboutCard hidden" id="nowSeriesAbout"></div>'''
one('</div></section><section class="view" id="view-library">','</div>'+picker+'</section><section class="view" id="view-library">','insert NOW picker')

# Listen dock owns only progress + exactly five controls; Library header owns title.
one('<b id="libListenTitle">Listen</b>','','remove Listen title')

# CONFIG includes Sources.
one('<button class="cfgTab" data-cfgtab="about">About</button>','<button class="cfgTab" data-cfgtab="sources">Sources</button><button class="cfgTab" data-cfgtab="about">About</button>','Sources tab')
sources_panel='''<div class="cfgPanel card" id="cfgSources" style="padding:14px"><h2>Sources</h2><p class="rowMeta">Canonical repository-backed registration control plane. Pages stores no repository credential.</p><div class="field"><label>Ticker / name</label><input id="sourceQuery" autocomplete="off" placeholder="DOW, NVDA, VOO…"></div><div class="field"><label>Instrument class</label><select id="sourceClass"><option value="index">index</option><option value="equity">equity</option><option value="etf">ETF</option><option value="fund_cit">fund / CIT / NAV</option></select></div><div class="actions left"><button class="btn" id="sourceResolve">Resolve identity</button><button class="btn" id="sourceRegister">Submit registration</button><button class="btn" id="sourceRefresh">Refresh</button></div><div class="cfgNote" id="sourceStatus"></div><div id="sourceResolution" class="providerCard hidden"></div><div id="sourceList" class="providerCard"></div></div>'''
one('<div class="cfgPanel card" id="cfgAbout"',sources_panel+'<div class="cfgPanel card" id="cfgAbout"','Sources panel')

# Credential fields are replacement-only once a provider is registered.
for p in ['venice','openrouter','anthropic']:
    old=f'<div class="field"><label>API key</label><input id="{p}Key"'
    new=f'<div class="field" data-key-row="{p}"><label>API key</label><input id="{p}Key"'
    one(old,new,f'{p} key row')
one('<div class="actions left"><button class="btn" id="veniceLoad">','<div class="actions left"><button class="btn" data-replace-key="venice">Replace key</button><button class="btn" id="veniceLoad">','venice replace')
one('<div class="actions left"><button class="btn" id="openrouterLoad">','<div class="actions left"><button class="btn" data-replace-key="openrouter">Replace key</button><button class="btn" id="openrouterLoad">','openrouter replace')
one('<div class="actions left"><button class="btn" id="anthropicValidate">','<div class="actions left"><button class="btn" data-replace-key="anthropic">Replace key</button><button class="btn" id="anthropicValidate">','anthropic replace')

# Turn 25 layout additions. Existing Turn 18 CSS remains the baseline styling.
css='''
/* TURN25_CONSOLIDATION */
#nowPicker{top:82px;right:12px;bottom:12px}.nowAddChip{border-style:dashed!important}.nowRemove{font-weight:900;margin-left:3px}.cfgSourceRow{padding:7px 0;border-bottom:1px solid var(--grid)}.cfgSourceRow:last-child{border-bottom:0}.sourceBad{color:var(--bad)}.sourceGood{color:var(--good)}[data-key-row].hidden{display:none!important}.libListenBar{grid-template-columns:repeat(5,40px)!important;grid-template-rows:auto 40px;justify-content:center}.libListenStatus{grid-column:1/-1;text-align:center}.libListenStatus span{display:block!important}.chartCard{height:100%}.now{height:100%}
@media(max-width:700px){.libListenBar{grid-template-columns:repeat(5,34px)!important;grid-template-rows:auto 36px;justify-content:center}.nowPicker{left:6px!important;right:6px!important;width:auto!important}.chartChromeRow{grid-template-columns:minmax(52px,1fr) max-content minmax(32px,1fr)}}
'''
one('</style>',css+'</style>','Turn25 CSS')

# Extend only the Turn 18 state object; no later application source is a donor.
one('analysisChartState:null};','analysisChartState:null,componentsExpanded:false,hiddenComponents:[],nowComparisons:[],nowRepresentation:null,nowPickerCat:"Other",nowPaint25:null,geometryRAF25:0,sourceRegistry:null,keyReplace25:{}};','state extension')

# Horizon capability truth: persisted-source capability and cadence govern availability.
between('async function seriesAvailability(','async function seriesAvailable(',r'''async function seriesAvailability(id,h=S.h,k=S.index||'risk'){try{let src=await getSeries(id),meta=cat(id),hh=health(id),cadence=String(meta.native_cadence||hh.cadence||'').toLowerCase(),supported=meta.supported_horizons||meta.supportedHorizons||hh.supportedHorizons||null;if(Array.isArray(supported)&&supported.length&&!supported.includes(h))return{available:false,reason:'unsupported-horizon',count:0};if(h==='1D'&&!/intraday|minute|hour/.test(cadence))return{available:false,reason:'intraday-required',count:0};let inside=obsRange(src,horizonWindow(h,k)).length,periodic=(id==='gdpQoq'||id==='gdpYoy'||cadence.includes('month')||cadence.includes('quarter'));if(inside>0)return{available:true,reason:'in-window',count:inside};if(periodic&&(src.observations||[]).length&&hh.classification!=='failed')return{available:true,reason:(id==='gdpQoq'||id==='gdpYoy')?'periodic-transform':'periodic-current',count:0};if((cadence.includes('daily')||cadence.includes('trading')||cadence.includes('nav'))&&hh.horizonCoverage?.[h]&&(src.observations||[]).length)return{available:true,reason:'health-covered',count:0};return{available:false,reason:'no-real-observation',count:0}}catch(e){return{available:false,reason:'evidence-error',error:String(e?.message||e)}}}''','series availability')

# Unified NOW breadcrumb. COMPONENTS is a terminal state label, never a page.
between('function nowBreadcrumbText()','function footerOptions(',r'''function nowBreadcrumbText(){if(S.level===1)return'ENV';let x=`ENV / ${AB[S.index]}`;return S.componentsExpanded?x+' / COMPONENTS':x}function renderNowCrumb(){let c=$('nowCrumb');if(!c)return;let full=nowBreadcrumbText();c.title=full;c.setAttribute('aria-label',full);if(S.level===1){c.innerHTML='<span class="chromeCrumbText">ENV</span>';return}c.innerHTML=`<span class="chromeCrumbText"><button class="crumbBtn" id="crumbEnvironment">ENV</button><span class="crumbSep"> / </span><button class="crumbBtn" id="crumbIndex22">${AB[S.index]}</button>${S.componentsExpanded?'<span class="crumbSep"> / </span><span>COMPONENTS</span>':''}</span>`;$('crumbEnvironment').onclick=()=>{S.level=1;S.index=null;S.componentsExpanded=false;S.hiddenComponents=[];S.nowComparisons=[];S.nowActive=null;S.nowFocus=null;$('info').classList.add('hidden');$('nowTip').style.display='none';renderV1()};$('crumbIndex22').onclick=()=>{S.componentsExpanded=false;S.hiddenComponents=[];S.nowActive=S.index;S.nowFocus=S.index;$('info').classList.add('hidden');renderV2()}}''','breadcrumb')

# NOW footer is one representation surface. Anchored derived-index comparison is Indexed 100.
between('function footerOptions(','function renderCrumb(',r'''function setNowFooter(w,mode='indexed'){let text=mode==='dual'?'Native Y1 + Y2':mode==='native'?'Native Y1':'Indexed 100';$('nowMeta').innerHTML=`<span>TURN 25 CONSOLIDATION</span><span class="footerSep">|</span><span>${w.startLabel} → ${w.endLabel}</span><span class="footerSep">|</span><select id="nowRepresentation" aria-label="Chart representation"><option selected value="${mode}">${text}</option></select>`}''','footer')

# View navigation has only NOW/LIBRARY/HEALTH/CONFIG.
between('function renderCrumb()','document.querySelectorAll(\'[data-view]\')',r'''function renderCrumb(){let c=$('crumb');if(S.view==='now'){renderNowCrumb();return}c.textContent=S.view.toUpperCase();c.title=c.textContent}function nav(v){if(!['now','library','health','config'].includes(v))v='now';S.view=v;$('shell').classList.toggle('nowMode',v==='now');document.querySelectorAll('.view').forEach(x=>x.classList.toggle('on',x.id==='view-'+v));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('on',x.dataset.view===v));renderCrumb();if(v==='library')renderLibrary();if(v==='health')renderHealth()}''','nav')

# Rail is geometry-only. Actual repaint is scheduled from frozen current chart model.
one("$('toggle').onclick=()=>$('rail').classList.toggle('closed');","$('toggle').onclick=()=>{$('rail').classList.toggle('closed');scheduleGeometry25();setTimeout(scheduleGeometry25,170)};",'rail geometry')

# Frozen NOW lineage is exact and cumulative.
between('function captureNowState(','function nowAnalysisState(',r'''function captureNowState(sets,w,mode){let ids=sets.map(z=>z.id),state={lineage:S.level===1?'ENV':`ENV/${AB[S.index]}${S.componentsExpanded?'/COMPONENTS':''}`,root:S.level===1?null:S.index,active:S.level===1?null:(S.nowActive||S.index),series:ids,horizon:S.h,index:S.index||'risk',basketExpanded:!!S.componentsExpanded,evidence:ids.map(evidenceFor)};state.chart=chartSnapshotFromSets(state,sets,w,mode,'frozen-now');S.nowChartState=state;return state}''','capture NOW')

