new_now=r'''function renderV1(){S.level=1;S.index=null;S.componentsExpanded=false;S.hiddenComponents=[];S.nowComparisons=[];S.nowActive=null;S.nowFocus=null;$('v1btn').classList.add('hidden');$('nowTitle').textContent='ENV';renderCrumb();let w=windowFor(),colors=chartColors(IDX),sets=IDX.map(k=>{let x=S.derived.indices[k].horizons[S.h];return{id:k,label:AB[k],full:S.def.indices[k].name,unit:'Index',color:colors[k],renderType:'line',a:(x.curve||[]).map(p=>({t:+p.t,v:+p.v,idx:+p.v,raw:+p.v,sourceT:+p.t}))}});$('legend').innerHTML=sets.map(z=>`<button class="lg" data-id="${z.id}" title="${esc(z.full)}">${legendSample(z)}${esc(z.label)}</button>`).join('');$('legend').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openV2(b.dataset.id));$('range').textContent=`${w.startLabel} → ${w.endLabel}`;setNowFooter(w,'indexed');captureNowState(sets,w,'indexed');S.nowPaint25={sets,w,mode:'indexed'};draw('now',sets,w,'indexed')}async function openV2(k){S.level=2;S.index=k;S.componentsExpanded=true;S.hiddenComponents=[];S.nowComparisons=[];S.nowActive=k;S.nowFocus=k;$('info').classList.add('hidden');$('nowTip').style.display='none';await renderV2()}function componentIds25(){return(S.def.indices[S.index]?.components||[]).map(x=>x.id)}function visibleIds25(){let ids=[S.index];if(S.componentsExpanded)ids.push(...componentIds25().filter(id=>!S.hiddenComponents.includes(id)));ids.push(...S.nowComparisons.filter(id=>!ids.includes(id)));return ids}async function sourceSet25(id,w,color){if(IDX.includes(id)){let x=S.derived.indices[id].horizons[S.h];return{id,label:AB[id],full:S.def.indices[id].name,unit:'Index',color,renderType:'line',a:(x.curve||[]).map(p=>({t:+p.t,v:+p.v,idx:+p.v,raw:+p.v,sourceT:+p.t}))}}try{let src=await getSeries(id),a=indexed(src,w,1);return{id,label:label(id),full:name(id),unit:unit(id),color,renderType:'line',a}}catch{return{id,label:label(id),full:name(id),unit:unit(id),color,renderType:'line',a:[]}}}function removeNowSeries25(id){if(id===S.index)return;if(componentIds25().includes(id)){if(!S.hiddenComponents.includes(id))S.hiddenComponents.push(id)}else S.nowComparisons=S.nowComparisons.filter(x=>x!==id);if(S.nowActive===id){S.nowActive=S.index;S.nowFocus=S.index}renderV2()}function wireLongPress25(b,id){let t=null,long=false;b.addEventListener('pointerdown',()=>{long=false;t=setTimeout(()=>{long=true;showNowSeriesInfo25(id)},450)});for(let ev of ['pointerup','pointercancel','pointerleave'])b.addEventListener(ev,()=>{if(t)clearTimeout(t)});b.addEventListener('contextmenu',e=>{e.preventDefault();showNowSeriesInfo25(id)})}async function showNowSeriesInfo25(id){let box=$('nowSeriesAbout'),meta=IDX.includes(id)?{name:S.def.indices[id]?.name||AB[id],short_name:AB[id],native_unit:'Index',native_cadence:'derived'}:cat(id),hh=IDX.includes(id)?{classification:'derived',actualLatestCanonicalObservation:S.derived.commonMarketAnchor}:health(id);box.innerHTML=`<h3>${esc(IDX.includes(id)?AB[id]:label(id))} · ${esc(meta.name||name(id))}</h3><div class="kv"><span>Unit</span><span>${esc(meta.native_unit||'—')}</span><span>Cadence</span><span>${esc(meta.native_cadence||'—')}</span><span>Health</span><span>${esc(hh.classification||'unknown')}</span><span>Latest</span><span>${esc(hh.actualLatestCanonicalObservation||'—')}</span></div><div class="actions">${meta.source_reference_url?`<a class="btn" href="${esc(meta.source_reference_url)}" target="_blank" rel="noopener">Source</a>`:''}<button class="btn" id="closeNowSeriesAbout">×</button></div>`;box.classList.remove('hidden');$('closeNowSeriesAbout').onclick=()=>box.classList.add('hidden')}async function renderV2(){let seq=++S.v2RenderSeq,k=S.index,w=windowFor(S.h,k),ids=visibleIds25(),colors=chartColors(ids),sets=[];for(let id of ids)sets.push(await sourceSet25(id,w,colors[id]));if(seq!==S.v2RenderSeq)return;if(!sets.some(z=>z.id===S.nowActive&&z.a.length)){S.nowActive=k;S.nowFocus=k}$('nowTitle').textContent=AB[k];renderCrumb();$('range').textContent=`${w.startLabel} → ${w.endLabel}`;$('legend').innerHTML=sets.map(z=>`<button class="lg ${z.id===S.nowActive?'active':''} ${z.a.length?'':'empty'}" data-id="${z.id}" title="${esc(z.full)}${z.a.length?'':' · unavailable for '+S.h}" ${z.a.length?'':'disabled aria-disabled="true"'}>${legendSample(z)}${esc(z.label)}${z.id===k?'':`<span class="nowRemove" data-rm="${z.id}" aria-label="Remove ${esc(z.label)}">×</span>`}</button>`).join('')+`<button class="lg nowAddChip" id="nowAddSeries">+ Add</button>`;$('legend').querySelectorAll('[data-id]').forEach(b=>{let id=b.dataset.id;wireLongPress25(b,id);b.onclick=e=>{if(e.target.closest('[data-rm]')||b.disabled)return;if(id===k&&!S.componentsExpanded){S.componentsExpanded=true;S.hiddenComponents=[];S.nowActive=k;S.nowFocus=k;renderV2();return}S.nowActive=id;S.nowFocus=id;$('nowTip').style.display='none';renderV2()}});$('legend').querySelectorAll('[data-rm]').forEach(x=>x.onclick=e=>{e.stopPropagation();removeNowSeries25(x.dataset.rm)});$('nowAddSeries').onclick=()=>openNowPicker25();setNowFooter(w,'indexed');captureNowState(sets,w,'indexed');S.nowPaint25={sets,w,mode:'indexed'};draw('now',sets,w,'indexed')}function componentCard(id){showNowSeriesInfo25(id)}function pickerGroups25(id){let owner=Object.entries(S.def.indices).find(([,v])=>(v.components||[]).some(c=>c.id===id))?.[0];return owner?owner[0].toUpperCase()+owner.slice(1):'Other'}function openNowPicker25(){S.nowPickerCat='Other';$('nowPickerSearch').value='';$('nowPicker').classList.remove('hidden');renderNowPicker25()}async function renderNowPicker25(){let token=Date.now()+Math.random(),q=$('nowPickerSearch').value.toLowerCase(),groups=['Risk','Growth','Macro','Other'];S.nowPickerToken25=token;$('nowPickerCats').innerHTML=groups.map(x=>`<button class="cat ${S.nowPickerCat===x?'on':''}" data-now-cat="${x}">${x}</button>`).join('');$('nowPickerCats').querySelectorAll('[data-now-cat]').forEach(b=>b.onclick=()=>{S.nowPickerCat=b.dataset.nowCat;renderNowPicker25()});let ids=[...IDX,...S.catalog.series.map(x=>x.id).filter(id=>id!=='realGdp')].filter(id=>!visibleIds25().includes(id)).filter(id=>{let g=IDX.includes(id)?'Other':pickerGroups25(id);return g===S.nowPickerCat}).filter(id=>`${id} ${IDX.includes(id)?S.def.indices[id]?.name:name(id)} ${IDX.includes(id)?AB[id]:label(id)}`.toLowerCase().includes(q));let pairs=await Promise.all(ids.map(async id=>[id,IDX.includes(id)?true:await seriesAvailable(id)]));if(S.nowPickerToken25!==token)return;let ok=Object.fromEntries(pairs);$('nowPickerList').innerHTML=ids.map(id=>{let good=!!ok[id],meta=IDX.includes(id)?{native_unit:'Index',native_cadence:'derived'}:cat(id);return`<div class="row pickerRow ${good?'':'empty'}"><div class="rowMain"><strong>${esc(IDX.includes(id)?AB[id]:label(id))} · ${esc(IDX.includes(id)?S.def.indices[id]?.name:name(id))}</strong><span class="rowMeta">${esc(meta.native_unit||'—')} · ${esc(meta.native_cadence||'—')} · ${good?'available':'unavailable'} for ${S.h}</span></div><button class="btn" data-about-now="${id}">About</button><button class="btn" data-add-now="${id}" ${good?'':'disabled aria-disabled="true"'}>Add</button></div>`}).join('')||'<div class="rowMeta" style="padding:10px">No matching series.</div>';$('nowPickerList').querySelectorAll('[data-about-now]').forEach(b=>b.onclick=()=>showNowSeriesInfo25(b.dataset.aboutNow));$('nowPickerList').querySelectorAll('[data-add-now]').forEach(b=>b.onclick=()=>{if(b.disabled)return;let id=b.dataset.addNow;if(!S.nowComparisons.includes(id))S.nowComparisons.push(id);S.nowActive=id;S.nowFocus=id;$('nowPicker').classList.add('hidden');renderV2()})}$('nowPickerSearch').oninput=renderNowPicker25;$('nowPickerClose').onclick=()=>$('nowPicker').classList.add('hidden');'''
s=s[:i]+new_now+s[j:]

# Remove the obsolete Explore engine and the obsolete Component-modal engine.
