between('async function startAI(','function activeAnalyses(',r'''async function startAI(stateOverride=null){let now=new Date().toISOString(),reg=aiRegistry(),p=reg.defaultProvider||'venice',c=(reg.providers||{})[p]||{};if(!c.verified||!c.key||!c.model){openConfig('ai');setPStatus(p,'Register this provider before starting an Analysis',false);return}let state=stateOverride||nowAnalysisState(),rootLabel=state.root?displayLabel(state.root):'ENV',a={id:'a-'+Date.now(),title:`${rootLabel} · ${state.horizon}`,titleManual:false,status:'processing',createdAt:now,updatedAt:now,state,provider:p,model:c.model||'',turns:[{role:'assistant',content:'Processing…',at:now,processing:true}]};a=await persistAnalysis(a);let analysisId=a.id;S.activeAnalysis=analysisId;$('libraryWorkspace').classList.add('detailOpen');nav('library');renderLibrary();try{let out=await callAI([{role:'system',content:`You are Market Navigator, an evidence-first market research analyst. Canonical chart evidence is authoritative for the supplied series. Use current web research only to explain context or developments and cite every external claim with a working Markdown link. Produce a substantive analysis, never an empty response. Begin with one specific H1 Markdown title, then separate: Market read, What changed, Evidence quality/limitations, Current context, What to watch next. Evidence: ${JSON.stringify(aiEvidenceState(state))}`},{role:'user',content:'Analyze this exact chart state and evidence. Explain the important cross-series relationships, limitations caused by cadence/freshness, current context, and what would change the interpretation.'}],{web:true});let saved=analyses().find(x=>x.id===analysisId);if(!saved)return;saved.turns=saved.turns.filter(t=>!t.processing);saved.turns.push({role:'assistant',content:out,at:new Date().toISOString()});if(!saved.titleManual)saved.title=generatedAnalysisTitle(out,saved.title);saved.status='ready';saved.updatedAt=new Date().toISOString();await persistAnalysis(saved);if(S.activeAnalysis===analysisId)renderLibrary()}catch(e){let saved=analyses().find(x=>x.id===analysisId);if(!saved)return;saved.turns=saved.turns.filter(t=>!t.processing);saved.turns.push({role:'assistant',content:`**Analysis failed:** ${e.message}`,at:new Date().toISOString()});saved.status='failed';saved.updatedAt=new Date().toISOString();await persistAnalysis(saved);if(S.activeAnalysis===analysisId)renderLibrary()}}''','AI transition')

# Registered credentials are display state; replacement is explicit and reversible.
between('function renderAIConfig()','function providerEndpoints(',r'''function keyRow25(p){return document.querySelector(`[data-key-row="${p}"]`)}function renderAIConfig(){let r=aiRegistry(),ps=r.providers||{};$('defaultProvider').value=r.defaultProvider||'venice';for(let p of ['venice','openrouter','anthropic']){let q=ps[p]||{},replacing=!!S.keyReplace25[p],row=keyRow25(p),btn=document.querySelector(`[data-replace-key="${p}"]`);$(p+'Key').value='';row?.classList.toggle('hidden',!!q.verified&&!replacing);if(btn){btn.classList.toggle('hidden',!q.verified);btn.textContent=replacing?'Cancel replacement':'Replace key'}if(p==='anthropic')$('anthropicModel').value=q.model||'';else fillModelSelect(p+'Model',q.models||([q.model].filter(Boolean)),q.model);setPStatus(p,q.verified?`registered · ${q.model}`:(q.key?'saved · validation required':'not registered'),q.verified?true:null)}$('cfgSummary').textContent=`Default: ${providerName($('defaultProvider').value)}. Registered keys remain browser-local and are not repopulated into editable fields.`}function workingKey25(p){let typed=$(p+'Key').value.trim(),q=providerRec(p);return typed||q.key||''}''','credential render')
between('async function loadProviderModels(','$(\'veniceLoad\').onclick',r'''async function loadProviderModels(p){let key=workingKey25(p);if(!key){setPStatus(p,'enter key first',false);return}setPStatus(p,'loading models…');try{let ep=providerEndpoints(p),r=await fetch(ep.models,{cache:'no-store',headers:{Authorization:`Bearer ${key}`}}),x=await r.json();if(!r.ok)throw Error(x.error?.message||`HTTP ${r.status}`);let ids=(x.data||x.models||[]).map(m=>typeof m==='string'?m:(m.id||m.model)).filter(Boolean).sort();if(!ids.length)throw Error('no models returned');fillModelSelect(p+'Model',ids,providerRec(p).model);let reg=aiRegistry(),providers=reg.providers||{},prev=providers[p]||{};providers[p]={...prev,models:ids};if(!prev.verified)providers[p].key=key;saveAIRegistry({...reg,providers});setPStatus(p,`${ids.length} models loaded · choose one`,null)}catch(e){setPStatus(p,e.message,false)}}async function validateProvider(p){let prior=providerRec(p),key=workingKey25(p),model=p==='anthropic'?$('anthropicModel').value.trim():$(p+'Model').value;if(!key){setPStatus(p,'enter key first',false);return}if(!model){setPStatus(p,p==='anthropic'?'enter model first':'load models and choose one first',false);return}setPStatus(p,`validating ${model}…`);try{let ep=providerEndpoints(p),headers={'Content-Type':'application/json'},body;if(p==='anthropic'){headers['x-api-key']=key;headers['anthropic-version']='2023-06-01';body={model,max_tokens:8,messages:[{role:'user',content:'Reply OK'}]}}else{headers.Authorization=`Bearer ${key}`;body={model,messages:[{role:'user',content:'Reply OK'}],max_tokens:8}}let r=await fetch(ep.chat,{method:'POST',headers,body:JSON.stringify(body)}),x=await r.json();if(!r.ok)throw Error(x.error?.message||`HTTP ${r.status}`);let reg=aiRegistry(),providers=reg.providers||{};providers[p]={...prior,key,model,verified:true,verifiedAt:new Date().toISOString()};reg={...reg,providers,defaultProvider:reg.defaultProvider||p};saveAIRegistry(reg);S.keyReplace25[p]=false;setPStatus(p,`registered · ${model}`,true);renderAIConfig()}catch(e){setPStatus(p,e.message,false);if(prior.verified){let reg=aiRegistry(),providers=reg.providers||{};providers[p]=prior;saveAIRegistry({...reg,providers});S.keyReplace25[p]=true}}}''','credential validation')
