# Sources control plane consumes repository registry/Health and hands new requests to authenticated GitHub UI.
sources_js=r'''function sourceClassLabel25(x){return x==='fund_cit'?'fund / CIT / NAV':x}function sourceHealth25(id){let h=health(id),good=h.classification==='current';return{good,label:good?'healthy':(h.classification||'pending'),latest:h.actualLatestCanonicalObservation||'—'}}function renderSources25(msg='Canonical registry refreshed'){let reg=S.sourceRegistry||{registrations:[],aliases:{}};$('sourceStatus').textContent=msg;$('sourceList').innerHTML=(reg.registrations||[]).map(r=>{let q=sourceHealth25(r.id);return`<div class="cfgSourceRow" data-source-id="${esc(r.id)}"><strong>${esc(r.canonicalSymbol)} · ${esc(r.canonicalName)}</strong><div class="rowMeta">${esc(sourceClassLabel25(r.instrumentClass))} · ${esc(r.measure)} · ${esc(q.label)} · latest ${esc(q.latest)} · ${(r.supportedHorizons||[]).join(' ')}</div><div class="rowMeta">${(r.providerChain||[]).map(x=>esc(x.provider+': '+x.identifier)).join(' → ')}</div></div>`}).join('')||'<div class="rowMeta">No registered sources.</div>'}function resolveSource25(){let q=$('sourceQuery').value.trim(),cls=$('sourceClass').value,reg=S.sourceRegistry||{aliases:{},registrations:[]};if(!q){$('sourceResolution').classList.add('hidden');$('sourceStatus').textContent='Enter a ticker or name.';return null}let alias=(reg.aliases||{})[q.toUpperCase()+'|'+cls],rec=(reg.registrations||[]).find(x=>x.instrumentClass===cls&&(String(x.query).toUpperCase()===q.toUpperCase()||String(x.canonicalSymbol).toUpperCase()===q.toUpperCase()));let out=alias?{symbol:alias.symbol,name:alias.name,cls:alias.instrumentClass,measure:alias.measure,state:'resolved alias'}:rec?{symbol:rec.canonicalSymbol,name:rec.canonicalName,cls:rec.instrumentClass,measure:rec.measure,state:'registered'}:null;if(out){$('sourceResolution').innerHTML=`<strong>${esc(out.symbol)} · ${esc(out.name)}</strong><div class="rowMeta">${esc(sourceClassLabel25(out.cls))} · ${esc(out.measure)} · ${esc(out.state)}</div>`;$('sourceResolution').classList.remove('hidden');$('sourceStatus').textContent='Canonical identity resolved before admission.'}else{$('sourceResolution').innerHTML=`<strong>Repository resolver required</strong><div class="rowMeta">${esc(q)} · ${esc(sourceClassLabel25(cls))} · no silent proxy substitution</div>`;$('sourceResolution').classList.remove('hidden');$('sourceStatus').textContent='Unresolved locally; submit to the canonical repository resolver.'}return out}function submitSource25(){let q=$('sourceQuery').value.trim(),cls=$('sourceClass').value;if(!q){$('sourceStatus').textContent='Enter a ticker or name.';return}resolveSource25();let title=`[Market Navigator Source] ${q}`,body=`Query: ${q}\nClass: ${cls}\n\nResolve canonical economic identity, provider cascade, measurement semantics, evidence, Health and supported horizons. Do not substitute a proxy or similarly named security.`;window.open(`https://github.com/acmeproducts/stuff/issues/new?title=${encodeURIComponent(title)}&body=${encodeURIComponent(body)}`,'_blank','noopener')}async function refreshSources25(){try{S.sourceRegistry=await j('data/market-backend/source-registry.json');renderSources25()}catch(e){$('sourceStatus').textContent='Registry refresh failed: '+e.message}}$('sourceResolve').onclick=resolveSource25;$('sourceRegister').onclick=submitSource25;$('sourceRefresh').onclick=refreshSources25;'''
